const std=@import("std");const R=@import("experimental/retention_mutation.zig");const M=@import("experimental/hydration_mutation_core.zig");const B=@import("experimental/hydration_continuous_core.zig");
fn founder()M.Cohort{return .{.biomass=0.4,.support_mass=0.1,.organization=0.25,.reproduction_credit=0.3,.lineage=17,.generation=1};}
test "frozen five seed statistics symmetric proposals boundary expression repeatable"{for([_]u64{0,1,42,2027,std.math.maxInt(u64)})|seed|{var positive:u32=0;var negative:u32=0;for(100..131172)|id|{const p=R.proposal(seed,17,id,2);try std.testing.expectEqual(p,R.proposal(seed,17,id,2));if(p>0)positive+=1;if(p<0)negative+=1;const z=R.allocation(0,seed,17,id,2);const hi=R.allocation(1,seed,17,id,2);try std.testing.expectEqual(if(p>0)p else @as(f32,0),z);try std.testing.expectEqual(if(p<0)1+p else @as(f32,1),hi);}const events=positive+negative;const ratio=@as(f64,@floatFromInt(positive))/@as(f64,@floatFromInt(events));std.debug.print("RETENTION_STATS seed={d} n=131072 positive={d} negative={d} events={d} ratio={d}\n",.{seed,positive,negative,events,ratio});try std.testing.expect(events>=1740 and events<=2356);try std.testing.expect(ratio>=0.45 and ratio<=0.55);}}
test "actual fromzero daughters preserve legacy RNG fields and never prefill"{var expressed:usize=0;for(100..2148)|id|{var a=M.initialized(42);a.cohorts[0]=founder();var b=B.initialized(42);inline for(std.meta.fields(B.Cohort))|f|@field(b.cohorts[0],f.name)=@field(a.cohorts[0],f.name);var sa:M.Stats=.{.next_lineage=id};var sb:B.Stats=.{.next_lineage=id};const water=M.waterTotal(a);const carbon=M.carbon(a);try std.testing.expect(M.reproduceWithRetention(&a,0,&a,&sa,true,2027));try std.testing.expect(B.reproduce(&b,0,&b,&sb,true));try std.testing.expectEqual(a.rng,b.rng);for(0..4)|slot|{inline for(std.meta.fields(B.Cohort))|f|{if(comptime !std.mem.eql(u8,f.name,"retention_allocation"))try std.testing.expectEqual(@field(b.cohorts[slot],f.name),@field(a.cohorts[slot],f.name));}}try std.testing.expectEqual(@as(f32,0),a.cohorts[0].retention_allocation);try std.testing.expectEqual(water,M.waterTotal(a));try std.testing.expectApproxEqAbs(carbon,M.carbon(a),1e-6);if(a.cohorts[1].retention_allocation>0){expressed+=1;try std.testing.expectEqual(@as(f32,1.0/32.0),a.cohorts[1].retention_allocation);try std.testing.expectEqual(@as(f64,0),a.cohorts[1].stored_water);}}try std.testing.expect(expressed>0);std.debug.print("RETENTION_FROM_ZERO funded_births=2048 expressed={d} water_prefill=0 legacy_rng_unchanged=true\n",.{expressed});}
test "negative allocation returns funded inherited excess and nonmutating inherits"{var id:u64=100;while(id<10000 and R.proposal(2027,17,id,2)>=0):(id+=1){}try std.testing.expect(id<10000);for([_]bool{false,true})|mutate|{var a=M.initialized(42);var dest=M.initialized(1);a.cohorts[0]=founder();a.cohorts[0].retention_allocation=0.03125;a.cohorts[0].stored_water=M.waterCapacity(a.cohorts[0]);var stats:M.Stats=.{.next_lineage=id};const water=M.waterTotal(a)+M.waterTotal(dest);try std.testing.expect(M.reproduceWithRetention(&a,0,&dest,&stats,mutate,2027));try std.testing.expectApproxEqAbs(water,M.waterTotal(a)+M.waterTotal(dest),1e-15);if(mutate){try std.testing.expectEqual(@as(f32,0),dest.cohorts[0].retention_allocation);try std.testing.expectEqual(@as(f64,0),dest.cohorts[0].stored_water);try std.testing.expect(dest.liquid_return>0);}else{try std.testing.expectEqual(@as(f32,0.03125),dest.cohorts[0].retention_allocation);try std.testing.expect(dest.cohorts[0].stored_water>0);}}}
test "failure and disabled original wrappers preserve state and six draw history"{var a=M.initialized(1);var stats:M.Stats=.{.next_lineage=100};const before=a;const oldstats=stats;try std.testing.expect(!M.propagateWithRetention(&a,0,&a,&stats,42));try std.testing.expectEqualDeep(before,a);try std.testing.expectEqualDeep(oldstats,stats);a.cohorts[0]=founder();var b=a;var bs=stats;try std.testing.expect(M.reproduce(&a,0,&a,&stats,true));try std.testing.expect(M.reproduce(&b,0,&b,&bs,true));try std.testing.expectEqualDeep(a,b);}
test "independent Python SHA vector fixes domain tuple encoding"{var expected:[32]u8=undefined;_=try std.fmt.hexToBytes(&expected,"22de0612c574954403e2b358218acc48a6d4e34ee6d3c6831faac4b81c93456c");try std.testing.expectEqualDeep(expected,R.digest(42,17,123456,2));}
test "fromzero expressed daughter grows on finite resources and transmits allele"{var id:u64=100;while(id<2148 and R.proposal(2027,17,id,2)<=0):(id+=1){}try std.testing.expect(id<2148);var donor=M.initialized(42);donor.cohorts[0]=founder();var daughter=M.initialized(43);var stats:M.Stats=.{.next_lineage=id};try std.testing.expect(M.reproduceWithRetention(&donor,0,&daughter,&stats,true,2027));const allele=daughter.cohorts[0].retention_allocation;try std.testing.expect(allele>0);var carbon:f64=1;var oxygen:f64=1;for(0..48)|_|{const flux=M.step(&daughter,.{.temperature=303,.depth_km=0.002,.light=1,.carbon_available=@floatCast(carbon),.oxygen_carbon_capacity=@floatCast(oxygen)},3600);carbon+=@as(f64,flux.recycled)-flux.fixed;oxygen+=@as(f64,flux.fixed)-flux.recycled;try std.testing.expect(carbon>=0 and oxygen>=0);}var grandchild=M.initialized(44);try std.testing.expect(M.reproduceWithRetention(&daughter,0,&grandchild,&stats,false,2027));try std.testing.expectEqual(allele,grandchild.cohorts[0].retention_allocation);try std.testing.expectEqual(@as(u32,3),grandchild.cohorts[0].generation);try std.testing.expectEqual(@as(f64,0),M.waterTotal(donor)+M.waterTotal(daughter)+M.waterTotal(grandchild));}
